backend/app/api/session_security.py:
"""Capability authentication, bounded requests, and durable mutation replay."""
from __future__ import annotations
import asyncio
import base64
from datetime import datetime, timedelta, timezone
import hashlib
import hmac
import json
import re
from weakref import WeakValueDictionary
from fastapi import Request, Response
from fastapi.responses import JSONResponse
from backend.app.db.repository import SQLiteRepository, IdempotencyConflictError
from backend.app.core.logging import get_request_id as request_id

_SESSION_PATH = re.compile(r'^/api/v1/sessions/([^/]+)(?:/|$)')

def install_session_security(app, settings):
    locks: WeakValueDictionary[tuple[str, str], asyncio.Lock] = WeakValueDictionary()

    def error(status, code, message):
        return JSONResponse({'code': code, 'message': message, 'retryable': False, 'request_id': request_id(), 'turn_id': None, 'job_id': None}, status_code=status)

    @app.middleware('http')
    async def session_security(request: Request, call_next):
        match = _SESSION_PATH.match(request.url.path)
        if not match or request.method == 'OPTIONS':
            return await call_next(request)
        sid = match.group(1)
        repo = SQLiteRepository(settings.database_path)
        repo.initialize()
        row = repo.get_session(sid, include_deleted=True)
        header = request.headers.get('authorization', '')
        token = <REDACTED_SECRET_LITERAL>
        digest = hashlib.sha256(token.encode()).hexdigest()
        if row is None or not token or not hmac.compare_digest(row.token_hash, digest):
            return error(401, 'SESSION_AUTH_REQUIRED', 'A valid session capability is required.')
        if row.deleted_at:
            return error(410, 'SESSION_DELETED', 'This session has been deleted.')
        if datetime.fromisoformat(row.expires_at) <= datetime.now(timezone.utc):
            return error(410, 'SESSION_EXPIRED', 'This session has expired.')
        if request.method in ('GET', 'HEAD'):
            return await call_next(request)
        key = request.headers.get('x-idempotency-key', '')
        if not 8 <= len(key) <= 128:
            return error(400, 'IDEMPOTENCY_KEY_REQUIRED', 'Mutations require X-Idempotency-Key (8–128 characters).')
        body = bytearray()
        async for chunk in request.stream():
            body.extend(chunk)
            if len(body) > 2_100_000:
                return error(413, 'REQUEST_TOO_LARGE', 'The request exceeds the capture limit.')
        request._body = bytes(body)
        request_digest = hashlib.sha256(body).hexdigest()
        # A per-key lock serializes duplicate deliveries; SQLite retains replay across restart.
        lock_key = (sid, key)
        lock = locks.setdefault(lock_key, asyncio.Lock())
        async with lock:
            try:
                cached = repo.check_idempotency(sid, method=request.method, route=request.url.path,
                                               idempotency_key=key, request_digest=request_digest)
            except IdempotencyConflictError:
                return error(409, 'IDEMPOTENCY_CONFLICT', 'The key was already used with another request.')
            if cached.outcome == 'HIT' and cached.record and cached.record.response_json:
                saved = json.loads(cached.record.response_json)
                if saved.get('stream_completed'):
                    return error(409, 'STREAM_ALREADY_DELIVERED', 'This stream was already delivered; replay the displayed coaching text.')
                return Response(base64.b64decode(saved['body']), status_code=saved['status'], headers=saved['headers'])
            if cached.outcome == 'HIT':
                return error(409, 'ACTION_IN_PROGRESS_OR_UNCERTAIN', 'The earlier action is pending or its completion is uncertain; restore the session before retrying.')
            expires = (datetime.now(timezone.utc)+timedelta(hours=24)).isoformat()
            repo.save_idempotency(sid, method=request.method, route=request.url.path, idempotency_key=key,
                request_digest=request_digest, status='IN_PROGRESS', response_json=None, expires_at=expires)
            response = await call_next(request)
            if response.headers.get('content-type','').startswith('text/event-stream'):
                original = response.body_iterator
                async def track_stream():
                    completed = False
                    try:
                        async for chunk in original:
                            yield chunk
                        completed = True
                    finally:
                        try:
                            repo.save_idempotency(sid, method=request.method, route=request.url.path, idempotency_key=key,
                                request_digest=request_digest, status='COMPLETE' if completed else 'UNCERTAIN',
                                response_json=json.dumps({'stream_completed':True}) if completed else None, expires_at=expires)
                        except Exception:
                            pass  # Tombstoned sessions retain no private replay payload.
                response.body_iterator = track_stream()
                return response
            payload = b''.join([part async for part in response.body_iterator])
            headers = {k:v for k,v in response.headers.items() if k.lower() not in ('content-length','transfer-encoding')}
            # Deletion has tombstoned the row and is already repeat-safe (410 on retries).
            if request.method != 'DELETE' and response.status_code < 500:
                repo.save_idempotency(sid, method=request.method, route=request.url.path, idempotency_key=key,
                    request_digest=request_digest, status='COMPLETE',
                    response_json=json.dumps({'status':response.status_code,'headers':headers,'body':base64.b64encode(payload).decode()}),
                    expires_at=(datetime.now(timezone.utc)+timedelta(hours=24)).isoformat())
            return Response(payload, status_code=response.status_code, headers=headers)

backend/app/coaching/templates.py:
"""Deterministic 3-Level Socratic Coaching Templates (`backend/app/coaching/templates.py`).

Implements Plan §4 / §10 / P5 (T-06):
- Graduated 3-level Socratic hints:
  - Level 1 (`HintLevel.DIAGNOSTIC_QUESTION = 1`): Socratic question grounded in the concrete counterexample input and observed vs reference output.
  - Level 2 (`HintLevel.TRACE_STEP_POINTER = 2`): Dynamically points to the exact `TraceStep` (`event_id`, `source_line`, `locals_snapshot`) where state diverges or exits prematurely.
  - Level 3 (`HintLevel.REPAIR_PRINCIPLE = 3`): Conceptual invariant repair principle without dumping full copy-paste solution code.
- Supports all 3 canonical exercises (`ex1_shortest_subarray`, `ex2_binary_search`, `ex3_max_product`) and all learning states.
"""

from __future__ import annotations

from dataclasses import dataclass
from typing import Any

try:
    from backend.app.models.domain import (
        EvidenceArtifact,
        TraceExecutionReport,
        TraceStep,
    )
    from backend.app.models.enums import (
        ExerciseId,
        HintLevel,
        LearningState,
        PredictionStatus,
        SpecVersion,
        TraceAttributionStatus,
        VerificationStatus,
    )
except ImportError:  # pragma: no cover
    from app.models.domain import EvidenceArtifact, TraceExecutionReport, TraceStep  # type: ignore[no-redef]
    from app.models.enums import (  # type: ignore[no-redef]
        ExerciseId,
        HintLevel,
        LearningState,
        PredictionStatus,
        SpecVersion,
        TraceAttributionStatus,
        VerificationStatus,
    )


@dataclass(frozen=True)
class CoachingHintPrompt:
    hint_level: HintLevel
    display_text: str
    pointed_event_id: int | None
    pointed_line: int | None
    source_mode: str = "DETERMINISTIC_TEMPLATE"


def find_divergence_trace_step(
    trace_report: TraceExecutionReport | None,
) -> TraceStep | None:
    """Select the most informative attributed post-line `TraceStep` from a trace report."""
    if trace_report is None or not trace_report.steps:
        return None
    attributed = [
        s
        for s in trace_report.steps
        if s.attribution_status == TraceAttributionStatus.ATTRIBUTED
    ]
    if not attributed:
        return None
    pool = attributed
    # Prefer the step right before RETURN or at the deepest loop update
    non_call = [s for s in pool if str(s.event_kind) in ("LINE", "RETURN", "EXCEPTION")]
    if len(non_call) >= 2:
        return non_call[-2]
    return pool[-1]


def render_deterministic_hint(
    artifact: EvidenceArtifact,
    *,
    hint_level: HintLevel = HintLevel.DIAGNOSTIC_QUESTION,
    trace_report: TraceExecutionReport | None = None,
    learning_state: LearningState = LearningState.REPAIR_REQUIRED,
) -> CoachingHintPrompt:
    """Render a 100% deterministic, evidence-grounded coaching prompt without external LLM dependency."""
    ex_id = artifact.revision.exercise_id
    spec_ver = artifact.revision.spec_version
    inp = artifact.canonical_input
    obs = artifact.actual_observation
    ref_out = artifact.reference_output

    if artifact.prediction_status == PredictionStatus.NOT_EVALUATED and obs.kind.value == "UNAVAILABLE":
        return CoachingHintPrompt(
            hint_level=hint_level,
            display_text=(
                "Execution could not be completed, so your prediction has not been evaluated. "
                f"Verification status: {artifact.verification_report.status.value}. "
                "Keep your current code and prediction; retry when isolated execution is available."
            ),
            pointed_event_id=None,
            pointed_line=None,
        )

    if obs.kind.value not in ("RETURN", "UNAVAILABLE"):
        questions = {
            HintLevel.DIAGNOSTIC_QUESTION: "Which operation could cause this observed outcome on the revealed input?",
            HintLevel.TRACE_STEP_POINTER: "Inspect the reported exception and any available attributed trace step; a precise cause is not established by this record alone.",
            HintLevel.REPAIR_PRINCIPLE: "Propose one bounded change addressing the observed failure, then verify it; a timeout alone does not prove a particular bug.",
        }
        return CoachingHintPrompt(
            hint_level=hint_level,
            display_text=f"Execution reported {obs.kind.value} ({obs.error_type or 'no exception type reported'}). Your numerical prediction remains unevaluated. {questions[hint_level]}",
            pointed_event_id=None,
            pointed_line=None,
        )

    if learning_state == LearningState.PRACTICE_CHECKPOINT_COMPLETED:
        return CoachingHintPrompt(
            hint_level=hint_level,
            display_text=(
                f"Practice checkpoint completed for {ex_id.value} ({spec_ver.value}). "
                f"Your prediction and implementation both matched {ref_out} on the held-out transfer input {inp}."
            ),
            pointed_event_id=None,
            pointed_line=None,
        )

    if learning_state == LearningState.FRESH_CASE_CHECK:
        return CoachingHintPrompt(
            hint_level=hint_level,
            display_text=(
                f"Your code passed bounded verification ({artifact.verification_report.curated_cases_run} curated "
                f"and {artifact.verification_report.generated_cases_run} generated cases) and your prediction matched {ref_out}. "
                f"Now predict the output on a fresh held-out transfer case to complete this practice checkpoint."
            ),
            pointed_event_id=None,
            pointed_line=None,
        )

    if learning_state == LearningState.PREDICTION_REVIEW:
        return CoachingHintPrompt(
            hint_level=hint_level,
            display_text=(
                f"Your code returned the expected value {ref_out} on {inp}, "
                f"but you predicted {artifact.confirmed_prediction}. "
                f"Walk through how the loop state updates on {inp} and explain why the return value is {ref_out}."
            ),
            pointed_event_id=None,
            pointed_line=None,
        )

    observed_desc = (
        f"returned {obs.return_value}"
        if obs.return_value is not None
        else f"terminated with {obs.error_type or obs.kind.value}"
    )
    step = find_divergence_trace_step(trace_report)

    if hint_level == HintLevel.DIAGNOSTIC_QUESTION:
        if ex_id == ExerciseId.EX1_SHORTEST_SUBARRAY:
            if spec_ver == SpecVersion.EX1_V2_NEGATIVES_ALLOWED:
                q = (
                    f"On input {inp}, your code {observed_desc}, whereas the shortest subarray with sum >= "
                    f"{inp.get('target')} has length {ref_out}. When nums contains a negative number, "
                    f"is curr_sum still guaranteed to increase monotonically as right advances?"
                )
            else:
                q = (
                    f"On input {inp}, your code {observed_desc}, but the expected shortest length is {ref_out}. "
                    f"When curr_sum reaches {inp.get('target')}, how does your inner loop update best and shrink left?"
                )
        elif ex_id == ExerciseId.EX2_BINARY_SEARCH:
            q = (
                f"On input {inp}, your code {observed_desc}, while the first index with value >= "
                f"{inp.get('target')} is {ref_out}. When nums[mid] equals or exceeds target, "
                f"which half of the search range could still contain an earlier matching index?"
            )
        elif ex_id == ExerciseId.EX3_MAX_PRODUCT:
            q = (
                f"On input {inp}, your code {observed_desc}, while the maximum contiguous subarray product is {ref_out}. "
                f"When a negative number multiplies the previous minimum product, how should your running max and min update?"
            )
        else:
            from backend.app.exercises.registry import hints
            q = f'On input {inp}, your code {observed_desc}; the expected result is {ref_out}. ' + hints(ex_id.value)['1']
        return CoachingHintPrompt(
            hint_level=HintLevel.DIAGNOSTIC_QUESTION,
            display_text=q,
            pointed_event_id=None,
            pointed_line=None,
        )

    if hint_level == HintLevel.TRACE_STEP_POINTER:
        if step is not None:
            locals_preview = ", ".join(
                f"{k}={v}" for k, v in list(step.locals_snapshot.items())[:5]
            )
            text = (
                f"Inspect trace step #{step.event_id} after line {step.source_line} on input {inp}, "
                f"where locals are {{{locals_preview}}}. Compare that state against what is needed to reach {ref_out}."
            )
            return CoachingHintPrompt(
                hint_level=HintLevel.TRACE_STEP_POINTER,
                display_text=text,
                pointed_event_id=step.event_id,
                pointed_line=step.source_line,
            )
        return CoachingHintPrompt(
            hint_level=HintLevel.TRACE_STEP_POINTER,
            display_text=(
                f"Trace capture is unavailable or partial for {inp} ({observed_desc} vs expected {ref_out}). "
                f"Check the loop condition and accumulator update right before the return statement."
            ),
            pointed_event_id=None,
            pointed_line=None,
        )

    # Level 3: REPAIR_PRINCIPLE
    if ex_id == ExerciseId.EX1_SHORTEST_SUBARRAY:
        if spec_ver == SpecVersion.EX1_V2_NEGATIVES_ALLOWED:
            principle = (
                f"Repair Principle: Because negative values in {inp} break sliding-window monotonicity, "
                f"maintain prefix sums P[i] and a monotonic increasing deque of candidate start indices "
                f"so you can pop any front index where P[right] - P[front] >= target and pop any back index with P[back] >= P[right]."
            )
        else:
            principle = (
                f"Repair Principle: For positive integers on {inp}, advance right to add nums[right] to curr_sum, "
                f"and while curr_sum >= target, record min(best, right - left + 1) before subtracting nums[left] and incrementing left."
            )
    elif ex_id == ExerciseId.EX2_BINARY_SEARCH:
        principle = (
            f"Repair Principle: Initialize ans = -1, left = 0, right = len(nums) - 1. "
            f"Whenever nums[mid] >= target on {inp}, record ans = mid and set right = mid - 1 to keep searching left for an earlier duplicate; "
            f"otherwise set left = mid + 1."
        )
    elif ex_id == ExerciseId.EX3_MAX_PRODUCT:
        principle = (
            f"Repair Principle: On {inp}, update both running extrema simultaneously in a tuple assignment — "
            f"hi, lo = max(x, hi * x, lo * x), min(x, hi * x, lo * x) — so multiplying by a negative x uses the unmutated prior hi."
        )

    else:
        from backend.app.exercises.registry import hints
        principle = 'Repair Principle: ' + hints(ex_id.value)['3']
    return CoachingHintPrompt(
        hint_level=HintLevel.REPAIR_PRINCIPLE,
        display_text=principle,
        pointed_event_id=step.event_id if step else None,
        pointed_line=step.source_line if step else None,
    )

backend/app/core/execution_readiness.py:
"""Fail-closed public readiness from operator evidence and authenticated worker health."""
from __future__ import annotations

import json
from typing import Literal

import httpx

from backend.app.core.config import Settings

ExecutionReadiness = Literal["DISABLED", "BLOCKED_EXTERNAL", "READY"]


def has_operator_acceptance(settings: Settings) -> bool:
    """This checks claims only; the worker must bind them to its fresh runtime."""
    marker = settings.isolation_acceptance_file
    if marker is None:
        return False
    try:
        if not marker.is_file() or marker.stat().st_size > 65536:
            return False
        evidence = json.loads(marker.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return False
    if not isinstance(evidence, dict):
        return False
    return (
        evidence.get("status") == "VERIFIED"
        and evidence.get("runtime") == "runsc"
        and evidence.get("adversarial_acceptance_passed") is True
        and evidence.get("passed") is True
        and all(isinstance(evidence.get(key), str) and evidence[key] for key in (
            "runner_image_id", "runsc_sha256", "runtime_bundle_sha256",
            "runtime_version", "docker_daemon_id",
        ))
        and isinstance(evidence.get("runtime_config"), dict)
    )


async def probe_execution_readiness(settings: Settings) -> ExecutionReadiness:
    """Never equate a configuration flag or operator marker with live acceptance."""
    if not settings.allow_public_custom_code:
        return "DISABLED"
    if not settings.internal_worker_secret or not has_operator_acceptance(settings):
        return "BLOCKED_EXTERNAL"
    try:
        async with httpx.AsyncClient(timeout=2.0, follow_redirects=False) as client:
            response = await client.get(
                f"{settings.exec_worker_url.rstrip('/')}/internal/health",
                headers={"X-Internal-Worker-Secret": settings.internal_worker_secret.get_secret_value()},
            )
        if response.status_code != 200:
            return "BLOCKED_EXTERNAL"
        health = response.json()
    except (httpx.HTTPError, ValueError):
        return "BLOCKED_EXTERNAL"
    if isinstance(health, dict) and health.get("sandbox_ready") is True and health.get("acceptance_verified") is True:
        return "READY"
    return "BLOCKED_EXTERNAL"

backend/app/core/logging.py:
"""Structured JSON logging with request_id correlation and secret redaction."""

from contextvars import ContextVar, Token
from datetime import datetime, timezone
import json
import logging
import re
import sys
from typing import Any

_REQUEST_ID_CTX: ContextVar[str] = ContextVar("vcc_request_id", default="-")

_SENSITIVE_KEY_FRAGMENTS = (
    "api_key",
    "apikey",
    "secret",
    "token",
    "authorization",
    "password",
    "credential",
    "x-api-key",
)

_SECRET_VALUE_PATTERN = <REDACTED_SECRET_LITERAL>
    r"(?i)\b(bearer\s+[A-Za-z0-9._\-]+|sk-[A-Za-z0-9_\-]+|gsk_[A-Za-z0-9_\-]+)\b"
)

_STANDARD_RECORD_ATTRS = frozenset(
    {
        "args",
        "asctime",
        "created",
        "exc_info",
        "exc_text",
        "filename",
        "funcName",
        "levelname",
        "levelno",
        "lineno",
        "module",
        "msecs",
        "message",
        "msg",
        "name",
        "pathname",
        "process",
        "processName",
        "relativeCreated",
        "stack_info",
        "thread",
        "threadName",
        "taskName",
    }
)


def get_request_id() -> str:
    return _REQUEST_ID_CTX.get()


def set_request_id(request_id: str) -> Token[str]:
    return _REQUEST_ID_CTX.set(request_id)


def reset_request_id(token: Token[str]) -> None:
    _REQUEST_ID_CTX.reset(token)


def _is_sensitive_key(key: str) -> bool:
    lowered = key.lower()
    return any(fragment in lowered for fragment in _SENSITIVE_KEY_FRAGMENTS)


def _sanitize_value(value: Any, *, key: str | None = None) -> Any:
    if key is not None and _is_sensitive_key(key):
        return "[REDACTED]"
    if isinstance(value, dict):
        return {str(k): _sanitize_value(v, key=str(k)) for k, v in value.items()}
    if isinstance(value, (list, tuple)):
        return [_sanitize_value(item) for item in value]
    if isinstance(value, str):
        return _SECRET_VALUE_PATTERN.sub("[REDACTED]", value)
    return value


class JsonLogFormatter(logging.Formatter):
    """Formats log records as single-line JSON with secret redaction."""

    def format(self, record: logging.LogRecord) -> str:
        payload: dict[str, Any] = {
            "timestamp": datetime.now(timezone.utc).isoformat(),
            "level": record.levelname,
            "logger": record.name,
            "request_id": get_request_id(),
            "message": _sanitize_value(record.getMessage()),
        }
        for attr, val in record.__dict__.items():
            if attr in _STANDARD_RECORD_ATTRS or attr.startswith("_"):
                continue
            payload[attr] = _sanitize_value(val, key=attr)

        if record.exc_info and record.exc_info[0] is not None:
            payload["exception_type"] = record.exc_info[0].__name__

        return json.dumps(payload, default=str, separators=(",", ":"))


def configure_logging(level: str = "INFO") -> None:
    numeric_level = getattr(logging, level.upper(), logging.INFO)
    handler = logging.StreamHandler(sys.stdout)
    handler.setFormatter(JsonLogFormatter())

    root_logger = logging.getLogger()
    root_logger.handlers.clear()
    root_logger.addHandler(handler)
    root_logger.setLevel(numeric_level)


def get_logger(name: str) -> logging.Logger:
    return logging.getLogger(name)

backend/app/db/migrations.py:
"""SQLite WAL connection helper and versioned SQL migration runner."""

from __future__ import annotations

from dataclasses import dataclass
from datetime import datetime, timezone
import hashlib
from pathlib import Path
import re
import sqlite3

_MIGRATION_FILENAME_RE = re.compile(r"^(\d+)_([a-zA-Z0-9_]+)\.sql$")


class MigrationError(RuntimeError):
    """Raised when a migration is malformed, fails, or drifts from recorded checksums."""


@dataclass(frozen=True)
class AppliedMigration:
    version: str
    name: str
    checksum: str
    applied_at: str


def utc_now_iso() -> str:
    return datetime.now(timezone.utc).isoformat()


def open_connection(db_path: str | Path) -> sqlite3.Connection:
    """Open a SQLite connection configured with WAL mode and foreign key enforcement."""
    target = str(db_path)
    if target != ":memory:" and not target.startswith("file:"):
        Path(target).parent.mkdir(parents=True, exist_ok=True)
    conn = sqlite3.connect(target, isolation_level=None)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA journal_mode = WAL;")
    conn.execute("PRAGMA foreign_keys = ON;")
    conn.execute("PRAGMA synchronous = NORMAL;")
    conn.execute("PRAGMA busy_timeout = 5000;")
    return conn


def _split_sql_statements(sql: str) -> list[str]:
    """Split SQL text into individual complete statements without using executescript."""
    statements: list[str] = []
    buffer: list[str] = []
    for line in sql.splitlines(keepends=True):
        stripped = line.strip()
        if not buffer and (not stripped or stripped.startswith("--")):
            continue
        buffer.append(line)
        candidate = "".join(buffer)
        if sqlite3.complete_statement(candidate):
            cleaned = candidate.strip()
            if cleaned:
                statements.append(cleaned)
            buffer.clear()
    remainder = "".join(buffer).strip()
    if remainder:
        statements.append(remainder)
    return statements


def _ensure_migrations_table(conn: sqlite3.Connection) -> None:
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS schema_migrations (
            version TEXT PRIMARY KEY,
            name TEXT NOT NULL,
            checksum TEXT NOT NULL,
            applied_at TEXT NOT NULL
        );
        """
    )


def _discover_migrations(migrations_dir: Path) -> list[tuple[str, str, Path]]:
    if not migrations_dir.is_dir():
        raise MigrationError(f"Migrations directory does not exist: {migrations_dir}")
    discovered: list[tuple[int, str, str, Path]] = []
    seen_versions: set[str] = set()
    for path in sorted(migrations_dir.iterdir()):
        if not path.is_file() or path.suffix != ".sql":
            continue
        match = _MIGRATION_FILENAME_RE.match(path.name)
        if not match:
            raise MigrationError(f"Invalid migration filename: {path.name}")
        version, name = match.group(1), match.group(2)
        if version in seen_versions:
            raise MigrationError(f"Duplicate migration version: {version}")
        seen_versions.add(version)
        discovered.append((int(version), version, name, path))
    discovered.sort(key=lambda item: (item[0], item[1]))
    return [(version, name, path) for _, version, name, path in discovered]


def apply_migrations(
    db_path: str | Path,
    migrations_dir: str | Path | None = None,
) -> list[str]:
    """Apply all pending SQL migrations atomically and return newly applied versions."""
    resolved_dir = (
        Path(migrations_dir)
        if migrations_dir is not None
        else Path(__file__).with_name("migrations")
    )
    migrations = _discover_migrations(resolved_dir)
    applied_now: list[str] = []

    conn = open_connection(db_path)
    try:
        _ensure_migrations_table(conn)
        rows = conn.execute(
            "SELECT version, name, checksum, applied_at FROM schema_migrations ORDER BY version"
        ).fetchall()
        recorded = {row["version"]: row["checksum"] for row in rows}

        for version, name, path in migrations:
            sql_bytes = path.read_bytes()
            checksum = hashlib.sha256(sql_bytes).hexdigest()
            if version in recorded:
                if recorded[version] != checksum:
                    raise MigrationError(
                        f"Checksum mismatch for already-applied migration {version} ({name})"
                    )
                continue

            sql_text = sql_bytes.decode("utf-8")
            statements = _split_sql_statements(sql_text)
            if not statements:
                raise MigrationError(f"Migration {path.name} contains no SQL statements")

            conn.execute("BEGIN IMMEDIATE;")
            try:
                for stmt in statements:
                    conn.execute(stmt)
                conn.execute(
                    """
                    INSERT INTO schema_migrations (version, name, checksum, applied_at)
                    VALUES (?, ?, ?, ?);
                    """,
                    (version, name, checksum, utc_now_iso()),
                )
                conn.execute("COMMIT;")
            except sqlite3.Error as exc:
                conn.execute("ROLLBACK;")
                raise MigrationError(
                    f"Migration {path.name} failed and was rolled back: {exc}"
                ) from exc

            applied_now.append(version)
    finally:
        conn.close()

    return applied_now


def get_applied_migrations(db_path: str | Path) -> list[AppliedMigration]:
    """Return all recorded migrations ordered by version."""
    conn = open_connection(db_path)
    try:
        _ensure_migrations_table(conn)
        rows = conn.execute(
            "SELECT version, name, checksum, applied_at FROM schema_migrations ORDER BY version"
        ).fetchall()
        return [
            AppliedMigration(
                version=row["version"],
                name=row["name"],
                checksum=row["checksum"],
                applied_at=row["applied_at"],
            )
            for row in rows
        ]
    finally:
        conn.close()

