@router.post('/sessions/{sid}/proposals')
def preview(req: Request,sid: str,data: Proposal,authorization: str = Header(default=''),x_idempotency_key: str = Header(default='')):
    with connection(req) as c: auth(c,sid,authorization)
    parsed=Diagram.model_validate({'base_revision':data.base_revision,**data.graph}); graph=parsed.model_dump(exclude={'base_revision'})
    checked=evaluate(graph)
    if checked['structural_errors']: err(422,checked['structural_errors'])
    def act(conn):
        s=auth(conn,sid,authorization)
        if s['diagram_revision']!=data.base_revision: err(409,'Diagram revision conflict')
        pid=str(uuid.uuid4())
        conn.execute('INSERT INTO studio_proposals VALUES(?,?,?,?,?,?)',(pid,sid,data.base_revision,encode(graph),'pending',iso()))
        return {'proposal_id':pid,'base_revision':data.base_revision,'graph':graph,'validation':checked}
    return mutation(req,sid,x_idempotency_key,data.model_dump(),act)

@router.post('/sessions/{sid}/proposals/{pid}/{action}')
def proposal_action(req: Request,sid: str,pid: str,action: str,authorization: str = Header(default=''),x_idempotency_key: str = Header(default='')):
    if action not in ('accept','discard'): err(404,'Unknown action')
    with connection(req) as c: auth(c,sid,authorization)
    def act(conn):
        s=auth(conn,sid,authorization)
        p=conn.execute('SELECT * FROM studio_proposals WHERE id=? AND session_id=? AND status=?',(pid,sid,'pending')).fetchone()
        if not p: err(404,'Proposal unavailable')
        if action=='accept':
            if p['base_revision']!=s['diagram_revision']: err(409,'Diagram revision conflict')
            rev=s['diagram_revision']+1
            conn.execute('INSERT INTO studio_diagrams VALUES(?,?,?,?,?)',(sid,rev,s['diagram_revision'],p['graph_json'],iso()))
            conn.execute('UPDATE studio_sessions SET diagram_revision=?,epoch=epoch+1 WHERE id=?',(rev,sid))
            event(conn,sid,'diagram.updated',{'revision':rev,'epoch':s['epoch']+1})
        else: rev=s['diagram_revision']
        conn.execute('UPDATE studio_proposals SET status=? WHERE id=?',(action,pid))
        return {'status':action,'revision':rev,'epoch':s['epoch']+(action=='accept')}
    return mutation(req,sid,x_idempotency_key,{'action':action},act)

@router.get('/sessions/{sid}/summary')
def summary(req: Request,sid: str,authorization: str = Header(default='')):
    with connection(req) as conn:
        s=auth(conn,sid,authorization)
        count=conn.execute('SELECT count(*) FROM studio_turns WHERE session_id=?',(sid,)).fetchone()[0]
        dimensions=('algorithm_correctness','architecture_reasoning','codebase_comprehension','technical_communication')
        return {'session_id':sid,'scenario_id':s['scenario_id'],'turn_count':count,'dimensions':[{'dimension':d,'status':'abstained_insufficient_signal','evidence':[]} for d in dimensions]}

@router.get('/sessions/{sid}/export')
def export_session(req: Request,sid: str,authorization: str = Header(default='')):
    out=snapshot(req,sid,authorization)
    with connection(req) as conn:
        auth(conn,sid,authorization)
        out['turns']=[dict(r) for r in conn.execute('SELECT id,epoch,diagram_revision,kind,content,created_at FROM studio_turns WHERE session_id=? ORDER BY created_at',(sid,))]
    return out

backend/app/studio/validation.py:
"""Structural validation and bounded arithmetic, with explicit unknowns."""
from math import isfinite


def evaluate(graph: dict) -> dict:
    nodes, edges = graph['nodes'], graph['edges']
    ids = [n['node_id'] for n in nodes]
    errors = []
    if len(ids) != len(set(ids)): errors.append('duplicate_node_id')
    edge_ids = [e['edge_id'] for e in edges]
    if len(edge_ids) != len(set(edge_ids)): errors.append('duplicate_edge_id')
    if any(e['source_node_id'] not in ids or e['target_node_id'] not in ids for e in edges): errors.append('edge_endpoint_missing')
    a = graph['assumptions']
    calculations = {}
    def calc(name, keys, func):
        values = [a.get(k) for k in keys]
        if all(type(v) in (int,float) and isfinite(v) and v >= 0 for v in values):
            value = func(*values)
            if isfinite(value): calculations[name] = value
    calc('fanout_writes_per_second', ['event_rate_per_second','recipients_per_event'], lambda x,y:x*y)
    calc('origin_reads_per_second', ['read_rps','miss_fraction'], lambda x,y:x*y)
    calc('retry_storage_bytes', ['events_per_second','retry_window_seconds','bytes_per_event','replicas'], lambda w,x,y,z:w*x*y*z)
    return {'structural_errors': errors, 'calculations': calculations, 'mechanism_status': 'unknown', 'reason': 'Architecture guarantees require scenario-specific evidence.'}

backend/app/verification/minimizer.py:
"""Deterministic structural counterexample shrinker (`backend/app/verification/minimizer.py`).

Implements Plan §9.3 / P4 (T-05):
- Preserves legal domain invariants via `registry.validate_input(exercise_id, spec_version, candidate)`.
- Shrinks in 3 deterministic stages:
  Stage A: Array length reduction toward `spec.min_length` (prefix/suffix/element removal; preserves sorted order for `ex2_binary_search` and allows empty list `[]`).
  Stage B: Element magnitude reduction toward `0` or `spec.min_value` (`1` for `v1_positive_only`).
  Stage C: Target reduction toward boundary/sum values within `spec.target_bounds`.
- Enforces `shrink_wall_ms` (default 20,000 ms) and `max_probes` (default 25) budgets.
- Returns `(minimized_input, MinimizationStatus.SHRINK_COMPLETED | MinimizationStatus.BUDGET_LIMITED)`.
"""

from __future__ import annotations

from copy import deepcopy
import time
from typing import Any, Callable

try:
    from backend.app.exercises import registry as exercise_registry
    from backend.app.models.enums import MinimizationStatus
except ImportError:  # pragma: no cover
    from app.exercises import registry as exercise_registry  # type: ignore[no-redef]
    from app.models.enums import MinimizationStatus  # type: ignore[no-redef]


def _input_complexity_key(input_args: dict[str, Any]) -> tuple[int, int, int]:
    nums = input_args.get("nums", [])
    length = len(nums) if isinstance(nums, list) else 0
    mag_sum = sum(abs(int(x)) for x in nums) if isinstance(nums, list) else 0
    target_mag = abs(int(input_args["target"])) if "target" in input_args else 0
    return (length, mag_sum, target_mag)


def _generate_length_shrink_candidates(
    exercise_id: str,
    spec_version: str,
    current_input: dict[str, Any],
) -> list[dict[str, Any]]:
    spec = exercise_registry.get_spec(exercise_id, spec_version)
    nums = list(current_input["nums"])
    n = len(nums)
    if n <= spec.min_length:
        return []

    candidates: list[dict[str, Any]] = []

    def _try_add(new_nums: list[int]) -> None:
        if len(new_nums) < spec.min_length:
            return
        cand = deepcopy(current_input)
        cand["nums"] = sorted(new_nums) if spec.sorted_required else new_nums
        try:
            validated = exercise_registry.validate_input(exercise_id, spec_version, cand)
            if validated != current_input and validated not in candidates:
                candidates.append(validated)
        except ValueError:
            return

    if spec.min_length == 0:
        _try_add([])
    if n >= 2 and spec.min_length <= 1:
        _try_add([nums[0]])
        _try_add([nums[-1]])
        _try_add([nums[n // 2]])
    if n >= 4:
        mid = n // 2
        if mid >= spec.min_length:
            _try_add(nums[:mid])
            _try_add(nums[n - mid :])
    for idx in range(n):
        _try_add(nums[:idx] + nums[idx + 1 :])
    return candidates


def _generate_magnitude_shrink_candidates(
    exercise_id: str,
    spec_version: str,
    current_input: dict[str, Any],
) -> list[dict[str, Any]]:
    spec = exercise_registry.get_spec(exercise_id, spec_version)
    nums = list(current_input["nums"])
    candidates: list[dict[str, Any]] = []
    floor_val = max(0, spec.min_value) if spec.min_value > 0 else 0

    for idx, val in enumerate(nums):
        if val == floor_val:
            continue
        trial_values: list[int] = [floor_val]
        half = int(val / 2)
        if half != val and half not in trial_values:
            trial_values.append(half)
        if val < 0 and -1 >= spec.min_value and -1 not in trial_values:
            trial_values.append(-1)
        elif val > 1 and 1 not in trial_values:
            trial_values.append(1)

        for tv in trial_values:
            if not (spec.min_value <= tv <= spec.max_value):
                continue
            if abs(tv) >= abs(val) and tv != floor_val:
                continue
            new_nums = list(nums)
            new_nums[idx] = tv
            if spec.sorted_required:
                new_nums.sort()
            cand = deepcopy(current_input)
            cand["nums"] = new_nums
            try:
                validated = exercise_registry.validate_input(exercise_id, spec_version, cand)
                if validated != current_input and validated not in candidates:
                    candidates.append(validated)
            except ValueError:
                continue
    return candidates


def _generate_target_shrink_candidates(
    exercise_id: str,
    spec_version: str,
    current_input: dict[str, Any],
) -> list[dict[str, Any]]:
    spec = exercise_registry.get_spec(exercise_id, spec_version)
    if spec.target_bounds is None or "target" not in current_input:
        return []
    lo_t, hi_t = spec.target_bounds
    cur_t = int(current_input["target"])
    nums = list(current_input["nums"])
    candidates: list[dict[str, Any]] = []

    trial_targets: list[int] = []
    if lo_t <= 1 <= hi_t:
        trial_targets.append(1)
    if lo_t <= 0 <= hi_t:
        trial_targets.append(0)
    half_t = int(cur_t / 2)
    if lo_t <= half_t <= hi_t:
        trial_targets.append(half_t)
    if nums:
        total_sum = sum(nums)
        if lo_t <= total_sum <= hi_t:
            trial_targets.append(total_sum)
        max_elem = max(nums)
        if lo_t <= max_elem <= hi_t:
            trial_targets.append(max_elem)

    for tt in trial_targets:
        if abs(tt) >= abs(cur_t) and tt not in (0, 1):
            continue
        cand = deepcopy(current_input)
        cand["target"] = tt
        try:
            validated = exercise_registry.validate_input(exercise_id, spec_version, cand)
            if validated != current_input and validated not in candidates:
                candidates.append(validated)
        except ValueError:
            continue
    return candidates


def _typed_complexity(arguments: dict[str, Any]) -> tuple[int, int]:
    def weight(value: object) -> tuple[int, int]:
        if type(value) is list:
            parts = [weight(x) for x in value]
            return len(value) + sum(p[0] for p in parts), sum(p[1] for p in parts)
        if type(value) is str:
            return len(value), sum(ord(c) for c in value)
        return 0, abs(int(value))
    parts = [weight(v) for v in arguments.values()]
    return sum(p[0] for p in parts), sum(p[1] for p in parts)


def _typed_candidates(arguments: dict, schema: dict) -> list[dict]:
    def variants(value: object, rule: dict) -> list:
        if type(value) is bool:
            return [False] if value else []
        if type(value) is int:
            floor = min(rule['maximum'], max(rule['minimum'], 0))
            return [floor, int(value / 2)]
        if type(value) is str:
            return [value[:rule['min_length']], value[:len(value)//2], value[:-1]]
        result = [value[:rule['min_length']], value[:len(value)//2]]
        result += [value[:i] + value[i+1:] for i in range(len(value))]
        for i, item in enumerate(value):
            result += [value[:i] + [replacement] + value[i+1:] for replacement in variants(item, rule['items'])]
        if rule.get('sorted_required'):
            result = [sorted(v) for v in result]
        return result
    return [{**arguments, name: value} for name, rule in schema.items() for value in variants(arguments[name], rule)]


def _shrink_typed(exercise_id: str, spec_version: str, best: dict, reproduces_failure_fn: Callable,
                  shrink_wall_ms: int, max_probes: int, clock_fn: Callable) -> tuple[dict, MinimizationStatus]:
    deadline = clock_fn() + shrink_wall_ms / 1000
    probes = 0
    schema = exercise_registry.get_spec(exercise_id, spec_version).input_schema
    while True:
        improved = False
        for candidate in _typed_candidates(best, schema):
            if clock_fn() >= deadline or probes >= max_probes:
                return deepcopy(best), MinimizationStatus.BUDGET_LIMITED
            try:
                candidate = exercise_registry.validate_input(exercise_id, spec_version, candidate)
            except ValueError:
                continue
            if _typed_complexity(candidate) >= _typed_complexity(best):
                continue
            probes += 1
            if reproduces_failure_fn(deepcopy(candidate)):
                best, improved = candidate, True
                break
        if not improved:
            return deepcopy(best), MinimizationStatus.SHRINK_COMPLETED


def shrink_counterexample(
    exercise_id: str,
    spec_version: str,
    failing_input: dict[str, Any],
    reproduces_failure_fn: Callable[[dict[str, Any]], bool],
    *,
    shrink_wall_ms: int = 20_000,
    max_probes: int = 25,
    clock_fn: Callable[[], float] = time.monotonic,
) -> tuple[dict[str, Any], MinimizationStatus]:
    """Deterministically shrink a confirmed counterexample while preserving legal domain constraints."""
    best = exercise_registry.validate_input(exercise_id, spec_version, deepcopy(failing_input))
    if shrink_wall_ms <= 0 or max_probes <= 0:
        return best, MinimizationStatus.NOT_ATTEMPTED
    if spec_version == 'v1_typed_bounded':
        return _shrink_typed(exercise_id, spec_version, best, reproduces_failure_fn, shrink_wall_ms, max_probes, clock_fn)

    start_ts = clock_fn()
    probes_used = 0
    budget_exhausted = False

    def _within_budget() -> bool:
        nonlocal budget_exhausted
        elapsed_ms = int((clock_fn() - start_ts) * 1000)
        if elapsed_ms >= shrink_wall_ms or probes_used >= max_probes:
            budget_exhausted = True
            return False
        return True

    # Stage A: Shrink array length until minimal
    improved = True
    while improved and _within_budget():
        improved = False
        for cand in _generate_length_shrink_candidates(exercise_id, spec_version, best):
            if not _within_budget():
                break
            probes_used += 1
            if reproduces_failure_fn(deepcopy(cand)):
                best = cand
                improved = True
                break

    # Stage B: Shrink element magnitudes
    improved = True
    while improved and _within_budget():
        improved = False
        for cand in _generate_magnitude_shrink_candidates(exercise_id, spec_version, best):
            if not _within_budget():
                break
            probes_used += 1
            if _input_complexity_key(cand) < _input_complexity_key(best) and reproduces_failure_fn(
                deepcopy(cand)
            ):
                best = cand
                improved = True
                break

    # Stage C: Shrink target magnitude
    for cand in _generate_target_shrink_candidates(exercise_id, spec_version, best):
        if not _within_budget():
            break
        probes_used += 1
        if reproduces_failure_fn(deepcopy(cand)):
            best = cand
            break

    status = (
        MinimizationStatus.BUDGET_LIMITED
        if budget_exhausted
        else MinimizationStatus.SHRINK_COMPLETED
    )
    return deepcopy(best), status

exec_worker/runner/protocol.py:
"""Untrusted in-sandbox wire framing and strict parser (§9.2).

Defines the framed JSON protocol between the disposable runner container
(`exec_worker/runner/run_invocation.py`) and the parent trusted broker.
"""

from __future__ import annotations

from dataclasses import dataclass, field
import json
from typing import Any

from .safe_serializer import _safe_type_name

FRAME_BEGIN = "<<VCC_RUNNER_FRAME_V1_BEGIN>>"
FRAME_END = "<<VCC_RUNNER_FRAME_V1_END>>"
PROTOCOL_VERSION = "v1"

FORBIDDEN_LEARNER_KEYS: frozenset[str] = frozenset(
    {
        "reference_output",
        "challenge_id",
        "case_hash",
        "verification_status",
    }
)

_ALLOWED_MODES: frozenset[str] = frozenset({"execute", "trace"})

_ALLOWED_OBSERVATION_KINDS: frozenset[str] = frozenset(
    {
        "RETURN",
        "EXCEPTION",
        "TIMEOUT",
        "RESOURCE_LIMIT",
        "INVALID_RESULT",
        "UNAVAILABLE",
    }
)

_ALLOWED_TRACE_STATUSES: frozenset[str] = frozenset(
    {
        "COMPLETED",
        "PARTIAL",
        "TRACE_TIMEOUT",
        "TRACE_UNAVAILABLE",
        "TRACE_TAMPERED",
    }
)

_ALLOWED_TRACE_EVENT_KINDS: frozenset[str] = frozenset(
    {
        "CALL",
        "LINE",
        "RETURN",
        "EXCEPTION",
        "TRUNCATED",
    }
)

_ALLOWED_ATTRIBUTION_STATUSES: frozenset[str] = frozenset(
    {
        "ATTRIBUTED",
        "AMBIGUOUS",
        "UNAVAILABLE",
        "TAMPERED",
    }
)

_EXECUTE_ENVELOPE_KEYS: frozenset[str] = frozenset(
    {
        "protocol_version",
        "mode",
        "kind",
        "return_value",
        "error_type",
        "error_message",
        "stdout_excerpt",
        "stderr_excerpt",
        "duration_ms",
    }
)

_TRACE_ENVELOPE_KEYS: frozenset[str] = frozenset(
    {
        "protocol_version",
        "mode",
        "kind",
        "return_value",
        "error_type",
        "error_message",
        "stdout_excerpt",
        "stderr_excerpt",
        "duration_ms",
        "trace_status",
        "steps",
        "total_observed",
        "trace_truncated",
        "termination_reason",
    }
)

_TRACE_STEP_KEYS: frozenset[str] = frozenset(
    {
        "event_id",
        "frame_id",
        "parent_frame_id",
        "call_depth",
        "source_hash",
        "source_line",
        "event_kind",
        "attribution_status",
        "locals_snapshot",
        "truncated_values",
    }
)

MAX_EXCERPT_CHARS = 4096
MAX_ERROR_TYPE_CHARS = 128
MAX_ERROR_MESSAGE_CHARS = 1024
MAX_RETURN_INT_BITS = 4096


class ProtocolViolationError(ValueError):
    """Raised when raw output from the disposable runner violates the wire protocol."""

    def __init__(self, code: str, message: str) -> None:
        super().__init__(message)
        self.code = code
        self.message = message


@dataclass(frozen=True)
class ParsedRunnerOutput:
    """Validated, sanitized result parsed from the runner's framed output."""

    mode: str
    kind: str
    return_value: int | bool | str | list[int | bool | str] | None
    error_type: str | None
    error_message: str | None
    stdout_excerpt: str
    stderr_excerpt: str
    duration_ms: int
    trace_status: str | None = None
    steps: list[dict[str, Any]] = field(default_factory=list)
    total_observed: int = 0
    trace_truncated: bool = False
    termination_reason: str | None = None


def is_strict_int(val: object) -> bool:
    """Return True if and only if `val` is an exact built-in `int` (never `bool`)."""
    return type(val) is int


def truncate_utf8_bytes(text: str | bytes, max_bytes: int) -> str:
    """Truncate `text` to at most `max_bytes` UTF-8 bytes and at most 4096 characters."""
    if type(max_bytes) is not int or max_bytes < 0:
        raise ValueError("max_bytes must be a non-negative integer")
    if isinstance(text, bytes):
        raw_bytes = text[:max_bytes]
        decoded = raw_bytes.decode("utf-8", errors="replace")
    elif type(text) is str:
        encoded = text.encode("utf-8", errors="replace")
        if len(encoded) > max_bytes:
            decoded = encoded[:max_bytes].decode("utf-8", errors="ignore")
        else:
            decoded = text
    else:
        raise TypeError("text must be str or bytes")

    if len(decoded) > MAX_EXCERPT_CHARS:
        decoded = decoded[:MAX_EXCERPT_CHARS]
    return decoded


def classify_learner_return_value(
    raw_value: object,
) -> tuple[str, int | bool | str | list[int | bool | str] | None, str | None, str | None]:
    """Classify a raw return value from learner code."""
    def scalar(value: object) -> bool:
        if type(value) is int:
            return -(2**53-1) <= value <= 2**53-1
        if type(value) is bool:
            return True
        if type(value) is str:
            return len(value) <= 256
        return False

    if scalar(raw_value):
        return ('RETURN', raw_value, None, None)
    if type(raw_value) is list and len(raw_value) <= 128 and all(scalar(v) for v in raw_value):
        return ('RETURN', list(raw_value), None, None)
    type_name = 'NoneType' if raw_value is None else _safe_type_name(raw_value)
    return ('INVALID_RESULT', None, 'InvalidReturnType',
        f'Expected bounded strict integer, boolean, string or scalar list; got {type_name}')


def build_execute_envelope(
    *,
    kind: str,
    return_value: object = None,
    error_type: str | None = None,
    error_message: str | None = None,
    stdout_text: str | bytes = "",
    stderr_text: str | bytes = "",
    duration_ms: int = 0,
    max_stdout_bytes: int = 65536,
    max_stderr_bytes: int = 65536,
) -> dict[str, Any]:
    """Build a strictly typed single-case execution envelope ready for framing."""
    if kind == "RETURN":
        kind, validated_ret, err_t, err_m = classify_learner_return_value(return_value)
        if kind != "RETURN":
            error_type = err_t
            error_message = err_m
    else:
        validated_ret = None

    if kind not in _ALLOWED_OBSERVATION_KINDS:
        raise ValueError(f"Unsupported observation kind: {kind}")

    safe_duration = duration_ms if (type(duration_ms) is int and duration_ms >= 0) else 0
    return {
        "protocol_version": PROTOCOL_VERSION,
        "mode": "execute",
        "kind": kind,
        "return_value": validated_ret,
        "error_type": (error_type[:MAX_ERROR_TYPE_CHARS] if type(error_type) is str else None),
        "error_message": (
            error_message[:MAX_ERROR_MESSAGE_CHARS] if type(error_message) is str else None
        ),
        "stdout_excerpt": truncate_utf8_bytes(stdout_text, max_stdout_bytes),
        "stderr_excerpt": truncate_utf8_bytes(stderr_text, max_stderr_bytes),
        "duration_ms": safe_duration,
    }


def build_trace_envelope(
    *,
    kind: str,
    return_value: object = None,
    error_type: str | None = None,
    error_message: str | None = None,
    stdout_text: str | bytes = "",
    stderr_text: str | bytes = "",
    duration_ms: int = 0,
    trace_status: str,
    steps: list[dict[str, Any]],
    total_observed: int,
    trace_truncated: bool,
    termination_reason: str,
    max_stdout_bytes: int = 65536,
    max_stderr_bytes: int = 65536,
) -> dict[str, Any]:
    """Build a strictly typed trace execution envelope ready for framing."""
    base = build_execute_envelope(
        kind=kind,
        return_value=return_value,
        error_type=error_type,
        error_message=error_message,
        stdout_text=stdout_text,
        stderr_text=stderr_text,
        duration_ms=duration_ms,
        max_stdout_bytes=max_stdout_bytes,
        max_stderr_bytes=max_stderr_bytes,
    )
    if trace_status not in _ALLOWED_TRACE_STATUSES:
        raise ValueError(f"Unsupported trace status: {trace_status}")
    safe_reason = (
        termination_reason[:256]
        if (type(termination_reason) is str and len(termination_reason) > 0)
        else "trace_completed"
    )
    base["mode"] = "trace"
    base["trace_status"] = trace_status
    base["steps"] = list(steps)
    base["total_observed"] = (
        total_observed if (type(total_observed) is int and total_observed >= 0) else 0
    )
    base["trace_truncated"] = bool(trace_truncated)
    base["termination_reason"] = safe_reason
    return base


def emit_runner_frame(
    payload: dict[str, Any],
    *,
    max_payload_bytes: int | None = None,
) -> str:
    """Serialize `payload` to compact JSON wrapped in `FRAME_BEGIN` / `FRAME_END`."""
    if type(payload) is not dict:
        raise ProtocolViolationError("INVALID_PAYLOAD", "Runner payload must be a JSON object")

    for forbidden in FORBIDDEN_LEARNER_KEYS:
        if forbidden in payload:
            raise ProtocolViolationError(
                "FORBIDDEN_KEY",
                f"Learner payload may never include forbidden key '{forbidden}'",
            )

    serialized = (
        json.dumps(
            payload,
            separators=(",", ":"),
            ensure_ascii=True,
            allow_nan=False,
        )
        .replace("<", "\\u003c")
        .replace(">", "\\u003e")
    )
    if max_payload_bytes is not None:
        encoded_len = len(serialized.encode("utf-8"))
        if encoded_len > max_payload_bytes:
            raise ProtocolViolationError(
                "PAYLOAD_TOO_LARGE",
                f"Serialized runner payload ({encoded_len} bytes) exceeds limit ({max_payload_bytes} bytes)",
            )
    return f"{FRAME_BEGIN}\n{serialized}\n{FRAME_END}\n"


def _reject_invalid_constant(constant: str) -> Any:
    raise ProtocolViolationError(
        "NON_STANDARD_JSON",
        f"Non-standard JSON constant '{constant}' is forbidden in runner frame",
    )


def _validate_trace_step_dict(step: object, index: int) -> dict[str, Any]:
    if type(step) is not dict:
        raise ProtocolViolationError(
            "INVALID_TRACE_STEP",
            f"Trace step at index {index} must be a JSON object",
        )
    step_keys = set(step.keys())
    forbidden_hit = step_keys & FORBIDDEN_LEARNER_KEYS
    if forbidden_hit:
        raise ProtocolViolationError(
            "FORBIDDEN_KEY",
            f"Trace step {index} contains forbidden key(s): {sorted(forbidden_hit)}",
        )
    if step_keys != _TRACE_STEP_KEYS:
        extra = step_keys - _TRACE_STEP_KEYS
        missing = _TRACE_STEP_KEYS - step_keys
        raise ProtocolViolationError(
            "INVALID_TRACE_STEP_KEYS",
            f"Trace step {index} has invalid keys (extra={sorted(extra)}, missing={sorted(missing)})",
        )

    event_id = step["event_id"]
    if type(event_id) is not int or event_id < 0:
        raise ProtocolViolationError(
            "INVALID_TRACE_STEP", f"Trace step {index} event_id must be a non-negative strict int"
        )

    frame_id = step["frame_id"]
    if type(frame_id) is not str or not (1 <= len(frame_id) <= 64):
        raise ProtocolViolationError(
            "INVALID_TRACE_STEP", f"Trace step {index} frame_id must be a non-empty string <= 64 chars"
        )

    parent_frame_id = step["parent_frame_id"]
    if parent_frame_id is not None and (
        type(parent_frame_id) is not str or not (1 <= len(parent_frame_id) <= 64)
    ):
        raise ProtocolViolationError(
            "INVALID_TRACE_STEP",
            f"Trace step {index} parent_frame_id must be None or string <= 64 chars",
        )

    call_depth = step["call_depth"]
    if type(call_depth) is not int or call_depth < 0:
        raise ProtocolViolationError(
            "INVALID_TRACE_STEP", f"Trace step {index} call_depth must be a non-negative strict int"
        )

    source_hash = step["source_hash"]
    if (
        type(source_hash) is not str
        or len(source_hash) != 64
        or any(ch not in "0123456789abcdef" for ch in source_hash)
    ):
        raise ProtocolViolationError(
            "INVALID_TRACE_STEP", f"Trace step {index} source_hash must be a 64-char lowercase hex SHA-256"
        )

    source_line = step["source_line"]
    if type(source_line) is not int or source_line < 1:
        raise ProtocolViolationError(
            "INVALID_TRACE_STEP", f"Trace step {index} source_line must be a strict int >= 1"
        )

    event_kind = step["event_kind"]
    if type(event_kind) is not str or event_kind not in _ALLOWED_TRACE_EVENT_KINDS:
        raise ProtocolViolationError(
            "INVALID_TRACE_STEP", f"Trace step {index} has invalid event_kind: {event_kind!r}"
        )

    attribution_status = step["attribution_status"]
    if (
        type(attribution_status) is not str
        or attribution_status not in _ALLOWED_ATTRIBUTION_STATUSES
    ):
        raise ProtocolViolationError(
            "INVALID_TRACE_STEP",
            f"Trace step {index} has invalid attribution_status: {attribution_status!r}",
        )

    locals_snapshot = step["locals_snapshot"]
    if type(locals_snapshot) is not dict:
        raise ProtocolViolationError(
            "INVALID_TRACE_STEP", f"Trace step {index} locals_snapshot must be a dict"
        )

    truncated_values = step["truncated_values"]
    if type(truncated_values) is not list or any(type(x) is not str for x in truncated_values):
        raise ProtocolViolationError(
            "INVALID_TRACE_STEP", f"Trace step {index} truncated_values must be a list[str]"
        )

    return dict(step)


def parse_runner_frame(
    raw_stdout: str | bytes,
    *,
    expected_mode: str = "execute",
    max_result_bytes: int = 65536,
    max_trace_bytes: int = 262144,
    max_stdout_bytes: int = 65536,
    max_stderr_bytes: int = 65536,
    max_trace_steps: int = 250,
) -> ParsedRunnerOutput:
    """Strictly parse and validate a single framed JSON payload from the disposable runner."""
    if expected_mode not in _ALLOWED_MODES:
        raise ValueError(f"Unsupported expected_mode: {expected_mode}")

    byte_cap = max_trace_bytes if expected_mode == "trace" else max_result_bytes

    if isinstance(raw_stdout, bytes):
        raw_bytes = raw_stdout
    elif type(raw_stdout) is str:
        raw_bytes = raw_stdout.encode("utf-8", errors="replace")
    else:
        raise ProtocolViolationError("INVALID_STDOUT_TYPE", "Runner stdout must be bytes or str")

    framing_allowance = len(FRAME_BEGIN.encode("utf-8")) + len(FRAME_END.encode("utf-8")) + 64
    if len(raw_bytes) > byte_cap + framing_allowance:
        raise ProtocolViolationError(
            "FRAME_BYTE_CAP_EXCEEDED",
            f"Runner output ({len(raw_bytes)} bytes) exceeds protocol cap ({byte_cap} bytes)",
        )

    try:
        text = raw_bytes.decode("utf-8", errors="strict")
    except UnicodeDecodeError as exc:
        raise ProtocolViolationError(
            "INVALID_UTF8", f"Runner frame is not valid UTF-8: {exc}"
        ) from exc

    begin_count = text.count(FRAME_BEGIN)
    end_count = text.count(FRAME_END)

    if begin_count == 0 or end_count == 0:
        raise ProtocolViolationError(
            "MISSING_FRAME",
            "Runner output is missing required frame delimiters",
        )
    if begin_count > 1 or end_count > 1:
        raise ProtocolViolationError(
            "MULTIPLE_OR_SPOOFED_FRAMES",
            f"Detected multiple frame delimiters (begin={begin_count}, end={end_count}); possible frame spoofing",
        )

    begin_idx = text.find(FRAME_BEGIN)
    end_idx = text.find(FRAME_END)
    if end_idx < begin_idx:
        raise ProtocolViolationError(
            "INVERTED_FRAME_DELIMITERS",
            "FRAME_END appeared before FRAME_BEGIN",
        )

    leading_data = text[:begin_idx]
    trailing_data = text[end_idx + len(FRAME_END) :]

    if leading_data.strip() != "":
        raise ProtocolViolationError(
            "UNFRAMED_LEADING_DATA",
            "Unexpected data before FRAME_BEGIN on protocol channel",
        )
    if trailing_data.strip() != "":
        raise ProtocolViolationError(
            "TRAILING_DATA_AFTER_FRAME_END",
            "Unexpected trailing data after FRAME_END on protocol channel",
        )

    inner_json = text[begin_idx + len(FRAME_BEGIN) : end_idx].strip()
    inner_bytes = inner_json.encode("utf-8")
    if len(inner_bytes) > byte_cap:
        raise ProtocolViolationError(
            "PAYLOAD_BYTE_CAP_EXCEEDED",
            f"Inner JSON payload ({len(inner_bytes)} bytes) exceeds cap ({byte_cap} bytes)",
        )

    if not inner_json:
        raise ProtocolViolationError("EMPTY_FRAME", "Runner frame payload is empty")

    try:
        payload = json.loads(inner_json, parse_constant=_reject_invalid_constant)
    except ProtocolViolationError:
        raise
    except Exception as exc:
        raise ProtocolViolationError(
            "MALFORMED_JSON", f"Runner frame payload is not valid JSON: {exc}"
        ) from exc

    if type(payload) is not dict:
        raise ProtocolViolationError(
            "NON_OBJECT_JSON", "Runner frame JSON root must be an object"
        )

    payload_keys = set(payload.keys())
    forbidden_found = payload_keys & FORBIDDEN_LEARNER_KEYS
    if forbidden_found:
        raise ProtocolViolationError(
            "FORBIDDEN_KEY",
            f"Runner payload contains forbidden key(s): {sorted(forbidden_found)}",
        )

    expected_keys = (
        _TRACE_ENVELOPE_KEYS if expected_mode == "trace" else _EXECUTE_ENVELOPE_KEYS
    )
    if payload_keys != expected_keys:
        extra = payload_keys - expected_keys
        missing = expected_keys - payload_keys
        raise ProtocolViolationError(
            "UNEXPECTED_KEYS",
            f"Runner payload keys mismatch (extra={sorted(extra)}, missing={sorted(missing)})",
        )

    if payload["protocol_version"] != PROTOCOL_VERSION:
        raise ProtocolViolationError(
            "UNSUPPORTED_PROTOCOL_VERSION",
            f"Expected protocol_version {PROTOCOL_VERSION!r}, got {payload['protocol_version']!r}",
        )

    mode = payload["mode"]
    if mode != expected_mode:
        raise ProtocolViolationError(
            "MODE_MISMATCH",
            f"Expected mode {expected_mode!r}, got {mode!r}",
        )

    raw_kind = payload["kind"]
    if type(raw_kind) is not str or raw_kind not in _ALLOWED_OBSERVATION_KINDS:
        raise ProtocolViolationError(
            "INVALID_OBSERVATION_KIND",
            f"Invalid observation kind: {raw_kind!r}",
        )

    raw_return_value = payload["return_value"]
    raw_error_type = payload["error_type"]
    raw_error_message = payload["error_message"]

    if raw_error_type is not None and type(raw_error_type) is not str:
        raise ProtocolViolationError("INVALID_ERROR_TYPE", "error_type must be str or null")
    if raw_error_message is not None and type(raw_error_message) is not str:
        raise ProtocolViolationError(
            "INVALID_ERROR_MESSAGE", "error_message must be str or null"
        )

    stdout_excerpt = payload["stdout_excerpt"]
    stderr_excerpt = payload["stderr_excerpt"]
    if type(stdout_excerpt) is not str or type(stderr_excerpt) is not str:
        raise ProtocolViolationError(
            "INVALID_STDIO_EXCERPT", "stdout_excerpt and stderr_excerpt must be strings"
        )

    duration_ms = payload["duration_ms"]
    if type(duration_ms) is not int or duration_ms < 0:
        raise ProtocolViolationError(
            "INVALID_DURATION", "duration_ms must be a non-negative strict integer"
        )

    effective_kind = raw_kind
    effective_return: int | bool | str | list[int | bool | str] | None = None
    effective_err_type = (
        raw_error_type[:MAX_ERROR_TYPE_CHARS] if raw_error_type is not None else None
    )
    effective_err_msg = (
        raw_error_message[:MAX_ERROR_MESSAGE_CHARS]
        if raw_error_message is not None
        else None
    )

    if raw_kind == "RETURN":
        classified_kind, classified_val, c_err_t, c_err_m = classify_learner_return_value(
            raw_return_value
        )
        effective_kind = classified_kind
        effective_return = classified_val
        if classified_kind != "RETURN":
            effective_err_type = c_err_t
            effective_err_msg = c_err_m
    else:
        if raw_return_value is not None:
            raise ProtocolViolationError(
                "NON_NULL_RETURN_ON_ERROR",
                f"Non-RETURN observation ({raw_kind}) must have return_value=null",
            )

    safe_stdout = truncate_utf8_bytes(stdout_excerpt, max_stdout_bytes)
    safe_stderr = truncate_utf8_bytes(stderr_excerpt, max_stderr_bytes)

    if expected_mode == "execute":
        return ParsedRunnerOutput(
            mode="execute",
            kind=effective_kind,
            return_value=effective_return,
            error_type=effective_err_type,
            error_message=effective_err_msg,
            stdout_excerpt=safe_stdout,
            stderr_excerpt=safe_stderr,
            duration_ms=duration_ms,
        )

    trace_status = payload["trace_status"]
    if type(trace_status) is not str or trace_status not in _ALLOWED_TRACE_STATUSES:
        raise ProtocolViolationError(
            "INVALID_TRACE_STATUS", f"Invalid trace_status: {trace_status!r}"
        )

    raw_steps = payload["steps"]
    if type(raw_steps) is not list:
        raise ProtocolViolationError("INVALID_TRACE_STEPS", "steps must be a list")
    if len(raw_steps) > max_trace_steps:
        raise ProtocolViolationError(
            "TRACE_STEPS_EXCEEDED",
            f"Trace steps count ({len(raw_steps)}) exceeds max_trace_steps ({max_trace_steps})",
        )

    validated_steps = [
        _validate_trace_step_dict(step_obj, idx) for idx, step_obj in enumerate(raw_steps)
    ]

    total_observed = payload["total_observed"]
    if type(total_observed) is not int or total_observed < 0:
        raise ProtocolViolationError(
            "INVALID_TOTAL_OBSERVED",
            "total_observed must be a non-negative strict integer",
        )

    trace_truncated = payload["trace_truncated"]
    if type(trace_truncated) is not bool:
        raise ProtocolViolationError(
            "INVALID_TRACE_TRUNCATED", "trace_truncated must be a strict boolean"
        )

    termination_reason = payload["termination_reason"]
    if type(termination_reason) is not str or not (1 <= len(termination_reason) <= 256):
        raise ProtocolViolationError(
            "INVALID_TERMINATION_REASON",
            "termination_reason must be a non-empty string <= 256 chars",
        )

    return ParsedRunnerOutput(
        mode="trace",
        kind=effective_kind,
        return_value=effective_return,
        error_type=effective_err_type,
        error_message=effective_err_msg,
        stdout_excerpt=safe_stdout,
        stderr_excerpt=safe_stderr,
        duration_ms=duration_ms,
        trace_status=trace_status,
        steps=validated_steps,
        total_observed=total_observed,
        trace_truncated=trace_truncated,
        termination_reason=termination_reason,
    )

exec_worker/runner/safe_serializer.py:
"""Safe bounded value serializer for trace local snapshots (§9.4, P2-03 & R5 repaired).

Security & Isolation Contract (Plan §9.4/§9.5 & Review Finding R5):
- Preserves the complete canonical serializer API (`SerializationBudget`,
  `SerializationResult`, `serialize_frame_locals`, `serialize_value`, `_safe_type_name`)
  AND exports `safe_repr` and `sanitize_Locals`.
- NEVER invokes untrusted `__repr__`, `__str__`, `__iter__`, `__len__`, `__getitem__`,
  `__getattr__`, `__getattribute__`, `__eq__`, `__hash__`, or custom metaclass
  descriptors/properties (including a hostile `@property def __name__(cls)` on a
  custom metaclass).
- In `_safe_type_name(val)`, `object.__getattribute__(cls, "__name__")` is NOT used
  because `type(cls)` is the metaclass and `object.__getattribute__` still invokes
  data descriptors on `type(cls)`! Instead, we inspect `type.__dict__["__name__"].__get__(cls, type)`
  ONLY when `type(cls) is type`, and otherwise inspect `type.__dict__["__dict__"].__get__(cls, type(cls))`
  for a plain `str` `"__name__"` entry or fall back to `"untrusted_object"`.
"""

from __future__ import annotations

from dataclasses import dataclass, field
import math
from types import FrameType, FunctionType, GeneratorType, ModuleType
from typing import Any

MAX_REPR_CHARS = 160
MAX_COLLECTION_ITEMS = 12
MAX_RECURSION_DEPTH = 3
MAX_TRACKED_LOCALS = 16

_REDACTED_LOCAL_NAMES: frozenset[str] = frozenset(
    {
        "__annotations__",
        "__builtins__",
        "__doc__",
        "__file__",
        "__loader__",
        "__name__",
        "__package__",
        "__spec__",
        "__vcc_tracer__",
        "__vcc_payload__",
        "__vcc_runner__",
    }
)


@dataclass(frozen=True)
class SerializationBudget:
    """Bounds enforced while serializing frame local snapshots."""

    max_depth: int = 4
    max_items: int = 20
    max_str_len: int = 128
    max_int_bits: int = 256
    max_nodes: int = 250


@dataclass(frozen=True)
class SerializationResult:
    """Result of safely serializing a value or frame locals dictionary."""

    value: Any
    truncated_values: list[str] = field(default_factory=list)
    nodes_visited: int = 0


def _safe_type_name(val: object) -> str:
    """Return a bounded class name without invoking any instance or metaclass descriptor (R5)."""
    cls = type(val)
    if type(cls) is type:
        try:
            raw_name = type.__dict__["__name__"].__get__(cls, type)
            if type(raw_name) is str:
                return raw_name[:64]
        except Exception:
            pass
        return "untrusted_object"

    try:
        cls_dict = type.__dict__["__dict__"].__get__(cls, type(cls))
        raw_name = cls_dict.get("__name__")
        if type(raw_name) is str:
            return raw_name[:64]
    except Exception:
        pass
    return "untrusted_object"


class _SafeSerializerState:
    def __init__(self, budget: SerializationBudget) -> None:
        self.budget = budget
        self.nodes_visited: int = 0
        self.active_ids: set[int] = set()
        self.truncated_paths: list[str] = []
        self._truncated_set: set[str] = set()

    def mark_truncated(self, path: str, reason: str) -> None:
        marker = f"{path}:{reason}" if path else reason
        if marker not in self._truncated_set:
            self._truncated_set.add(marker)
            self.truncated_paths.append(marker)

    def serialize(self, val: object, path: str, depth: int) -> Any:
        self.nodes_visited += 1
        if self.nodes_visited > self.budget.max_nodes:
            self.mark_truncated(path, "max_nodes")
            return {"__vcc_truncated__": "max_nodes"}

        val_type = type(val)

        if val is None:
            return None

        if val_type is bool:
            return True if val else False

        if val_type is int:
            bit_len = int.bit_length(val)
            if bit_len > self.budget.max_int_bits:
                self.mark_truncated(path, "max_int_bits")
                sign = "-" if val < 0 else "+"
                return {
                    "__vcc_truncated__": "max_int_bits",
                    "sign": sign,
                    "bit_length": bit_len,
                }
            return int(val)

        if val_type is float:
            if math.isnan(val):
                return {"__vcc_float__": "NaN"}
            if math.isinf(val):
                return {"__vcc_float__": "Infinity" if val > 0 else "-Infinity"}
            return float(val)

        if val_type is str:
            str_len = str.__len__(val)
            if str_len > self.budget.max_str_len:
                self.mark_truncated(path, "max_str_len")
                prefix = str.__getitem__(val, slice(0, self.budget.max_str_len))
                return prefix + "...[truncated]"
            return val

        if any(val_type is builtin for builtin in (list, tuple, set, frozenset, dict)):
            obj_id = id(val)
            if obj_id in self.active_ids:
                self.mark_truncated(path, "cycle")
                return {
                    "__vcc_cycle__": _safe_type_name(val),
                }

            if depth >= self.budget.max_depth:
                self.mark_truncated(path, "max_depth")
                return {
                    "__vcc_truncated__": "max_depth",
                    "type": _safe_type_name(val),
                }

            self.active_ids.add(obj_id)
            try:
                if val_type is list:
                    return self._serialize_sequence(val, path, depth)
                if val_type is tuple:
                    return self._serialize_sequence(val, path, depth)
                if val_type is set:
                    return self._serialize_set(val, path, depth)
                if val_type is frozenset:
                    return self._serialize_set(val, path, depth)
                if val_type is dict:
                    return self._serialize_dict(val, path, depth)
            finally:
                self.active_ids.discard(obj_id)

        return {"__vcc_untrusted_type__": _safe_type_name(val)}

    def _serialize_sequence(
        self, seq: list[Any] | tuple[Any, ...], path: str, depth: int
    ) -> list[Any]:
        out: list[Any] = []
        limit = self.budget.max_items
        iterator = list.__iter__(seq) if type(seq) is list else tuple.__iter__(seq)
        for idx, item in enumerate(iterator):
            if idx >= limit:
                self.mark_truncated(path, "max_items")
                break
            child_path = f"{path}[{idx}]" if path else f"[{idx}]"
            out.append(self.serialize(item, child_path, depth + 1))
            if self.nodes_visited > self.budget.max_nodes:
                break
        return out

    def _serialize_set(
        self, s: set[Any] | frozenset[Any], path: str, depth: int
    ) -> list[Any]:
        iterator = set.__iter__(s) if type(s) is set else frozenset.__iter__(s)
        out: list[Any] = []
        limit = self.budget.max_items
        for idx, item in enumerate(iterator):
            if idx >= limit:
                self.mark_truncated(path, "max_items")
                break
            child_path = f"{path}{{{idx}}}" if path else f"{{{idx}}}"
            out.append(self.serialize(item, child_path, depth + 1))
            if self.nodes_visited > self.budget.max_nodes:
                break
        return out

    def _serialize_dict(
        self, d: dict[Any, Any], path: str, depth: int
    ) -> dict[str, Any]:
        out: dict[str, Any] = {}
        limit = self.budget.max_items
        for idx, (k, v) in enumerate(dict.items(d)):
            if idx >= limit:
                self.mark_truncated(path, "max_items")
                break
            key_str = self._safe_dict_key(k, f"{path}.<key[{idx}]>" if path else f"<key[{idx}]>")
            child_path = f"{path}.{key_str}" if path else key_str
            out[key_str] = self.serialize(v, child_path, depth + 1)
            if self.nodes_visited > self.budget.max_nodes:
                break
        return out

    def _safe_dict_key(self, k: object, key_path: str) -> str:
        k_type = type(k)
        if k_type is str:
            if str.__len__(k) > self.budget.max_str_len:
                self.mark_truncated(key_path, "max_str_len")
                return str.__getitem__(k, slice(0, self.budget.max_str_len)) + "...[truncated]"
            return k
        if k is None:
            return "null"
        if k_type is bool:
            return "true" if k else "false"
        if k_type is int:
            if int.bit_length(k) > self.budget.max_int_bits:
                self.mark_truncated(key_path, "max_int_bits")
                return f"<int:{int.bit_length(k)}bits>"
            return int.__str__(k)
        if k_type is float:
            if math.isnan(k):
                return "NaN"
            if math.isinf(k):
                return "Infinity" if k > 0 else "-Infinity"
            return float.__str__(k)
        return f"<untrusted_key:{_safe_type_name(k)}>"


def serialize_value(
    val: object,
    budget: SerializationBudget | None = None,
    *,
    max_depth: int = 4,
    max_items: int = 20,
    max_str_len: int = 128,
    max_int_bits: int = 256,
    max_nodes: int = 250,
    root_path: str = "root",
) -> SerializationResult:
    effective_budget = budget or SerializationBudget(
        max_depth=max_depth,
        max_items=max_items,
        max_str_len=max_str_len,
        max_int_bits=max_int_bits,
        max_nodes=max_nodes,
    )
    state = _SafeSerializerState(effective_budget)
    serialized = state.serialize(val, root_path, depth=0)
    return SerializationResult(
        value=serialized,
        truncated_values=state.truncated_paths,
        nodes_visited=state.nodes_visited,
    )


def serialize_frame_locals(
    raw_locals: object,
    budget: SerializationBudget | None = None,
    *,
    max_depth: int = 4,
    max_items: int = 20,
    max_str_len: int = 128,
    max_int_bits: int = 256,
    max_nodes: int = 250,
) -> tuple[dict[str, Any], list[str]]:
    effective_budget = budget or SerializationBudget(
        max_depth=max_depth,
        max_items=max_items,
        max_str_len=max_str_len,
        max_int_bits=max_int_bits,
        max_nodes=max_nodes,
    )
    state = _SafeSerializerState(effective_budget)
    snapshot: dict[str, Any] = {}

    if type(raw_locals) is not dict:
        state.mark_truncated("locals", "non_dict_locals")
        return snapshot, state.truncated_paths

    count = 0
    for k, v in dict.items(raw_locals):
        if type(k) is not str:
            continue
        if k in _REDACTED_LOCAL_NAMES or str.startswith(k, "__vcc_"):
            continue
        if count >= effective_budget.max_items:
            state.mark_truncated("locals", "max_items")
            break
        count += 1
        snapshot[k] = state.serialize(v, k, depth=1)
        if state.nodes_visited > effective_budget.max_nodes:
            break

    return snapshot, state.truncated_paths


def safe_repr(
    val: Any,
    *,
    max_chars: int = MAX_REPR_CHARS,
    max_items: int = MAX_COLLECTION_ITEMS,
    _depth: int = 0,
    _active_ids: set[int] | None = None,
) -> str:
    """Produce a bounded, deterministic, hook-free string representation of `val`."""
    t = type(val)

    if val is None:
        return "None"
    if t is bool:
        return "True" if val else "False"
    if t is int:
        if int.bit_length(val) > 512:
            sign = "-" if val < 0 else "+"
            return f"<int {sign}{int.bit_length(val)}bits>"
        s = int.__repr__(val)
        return s if len(s) <= max_chars else s[: max_chars - 3] + "..."
    if t is float:
        if math.isnan(val):
            return "nan"
        if math.isinf(val):
            return "inf" if val > 0 else "-inf"
        s = float.__repr__(val)
        return s if len(s) <= max_chars else s[: max_chars - 3] + "..."
    if t is str:
        clipped = val if str.__len__(val) <= max_chars else str.__getitem__(val, slice(0, max_chars - 3)) + "..."
        s = str.__repr__(clipped)
        return s if len(s) <= max_chars else s[: max_chars - 3] + "..."
    if t is bytes:
        return f"<bytes len={bytes.__len__(val)}>"

    active = _active_ids if _active_ids is not None else set()
    if any(t is builtin for builtin in (list, tuple, set, frozenset, dict)):
        obj_id = id(val)
        if obj_id in active:
            return f"<cycle {_safe_type_name(val)}>"
        if _depth >= MAX_RECURSION_DEPTH:
            if t is list:
                return f"[... len={list.__len__(val)}]"
            if t is tuple:
                return f"(... len={tuple.__len__(val)})"
            if t is dict:
                return f"{{... len={dict.__len__(val)}}}"
            if t is set:
                return f"set(... len={set.__len__(val)})"
            return f"frozenset(... len={frozenset.__len__(val)})"

        active.add(obj_id)
        try:
            if t is list:
                n = list.__len__(val)
                parts: list[str] = []
                for idx, item in enumerate(list.__iter__(val)):
                    if idx >= max_items:
                        parts.append(f"... (+{n - max_items} more)")
                        break
                    parts.append(
                        safe_repr(
                            item,
                            max_chars=max(24, max_chars // 2),
                            max_items=max_items,
                            _depth=_depth + 1,
                            _active_ids=active,
                        )
                    )
                rendered = "[" + ", ".join(parts) + "]"
                return rendered if len(rendered) <= max_chars else rendered[: max_chars - 3] + "..."

            if t is tuple:
                n = tuple.__len__(val)
                parts = []
                for idx, item in enumerate(tuple.__iter__(val)):
                    if idx >= max_items:
                        parts.append(f"... (+{n - max_items} more)")
                        break
                    parts.append(
                        safe_repr(
                            item,
                            max_chars=max(24, max_chars // 2),
                            max_items=max_items,
                            _depth=_depth + 1,
                            _active_ids=active,
                        )
                    )
                suffix = "," if n == 1 else ""
                rendered = "(" + ", ".join(parts) + suffix + ")"
                return rendered if len(rendered) <= max_chars else rendered[: max_chars - 3] + "..."

            if t is set or t is frozenset:
                n = set.__len__(val) if t is set else frozenset.__len__(val)
                if n == 0:
                    return "set()" if t is set else "frozenset()"
                parts = []
                iterator = set.__iter__(val) if t is set else frozenset.__iter__(val)
                for idx, item in enumerate(iterator):
                    if idx >= max_items:
                        parts.append(f"... (+{n - max_items} more)")
                        break
                    parts.append(
                        safe_repr(
                            item,
                            max_chars=max(24, max_chars // 2),
                            max_items=max_items,
                            _depth=_depth + 1,
                            _active_ids=active,
                        )
                    )
                rendered = "{" + ", ".join(parts) + "}"
                return rendered if len(rendered) <= max_chars else rendered[: max_chars - 3] + "..."

            if t is dict:
                n = dict.__len__(val)
                parts = []
                for idx, (k, v) in enumerate(dict.items(val)):
                    if idx >= max_items:
                        parts.append(f"... (+{n - max_items} more)")
                        break
                    kr = safe_repr(k, max_chars=40, max_items=4, _depth=_depth + 1, _active_ids=active)
                    vr = safe_repr(
                        v,
                        max_chars=max(24, max_chars // 2),
                        max_items=max_items,
                        _depth=_depth + 1,
                        _active_ids=active,
                    )
                    parts.append(f"{kr}: {vr}")
                rendered = "{" + ", ".join(parts) + "}"
                return rendered if len(rendered) <= max_chars else rendered[: max_chars - 3] + "..."
        finally:
            active.discard(obj_id)

    if any(t is builtin for builtin in (FunctionType, GeneratorType, ModuleType, FrameType)) or t is type:
        return f"<{_safe_type_name(val)}>"

    return f"<{_safe_type_name(val)} object>"


def sanitize_Locals(
    raw_locals: dict[str, Any],
    *,
    max_locals: int = MAX_TRACKED_LOCALS,
    max_chars: int = MAX_REPR_CHARS,
) -> dict[str, str]:
    """Sanitize a frame's `f_locals` dictionary into hook-free string representations."""
    if type(raw_locals) is not dict:
        return {}
    out: dict[str, str] = {}
    count = 0
    for key, val in dict.items(raw_locals):
        if type(key) is not str:
            continue
        if key in _REDACTED_LOCAL_NAMES or str.startswith(key, "__"):
            continue
        if type(val) in (ModuleType, FunctionType, FrameType) or type(val) is type:
            continue
        out[str.__getitem__(key, slice(0, 64))] = safe_repr(val, max_chars=max_chars)
        count += 1
        if count >= max_locals:
            break
    return out

exec_worker/tests/test_serializer_identi:
"""Serialization must not compare an untrusted metaclass to built-in types."""
from exec_worker.runner.safe_serializer import serialize_value, safe_repr


def test_untrusted_metaclass_equality_and_hash_are_never_called():
    calls = []
    class HostileMeta(type):
        def __eq__(cls, other):
            calls.append('eq')
            raise AssertionError('Untrusted metaclass equality invoked')
        def __hash__(cls):
            calls.append('hash')
            raise AssertionError('Untrusted metaclass hash invoked')
    class Hostile(metaclass=HostileMeta):
        pass
    instance = Hostile()
    result = serialize_value(instance)
    assert result.value == {'__vcc_untrusted_type__': 'untrusted_object'}
    assert safe_repr(instance) == '<untrusted_object object>'
    assert calls == []


def test_invalid_return_classification_never_reads_metaclass_name():
    from exec_worker.runner.protocol import classify_learner_return_value
    class NameHook(type):
        @property
        def __name__(cls):
            raise AssertionError('Metaclass name hook invoked')
    class Fixture(metaclass=NameHook):
        pass
    result = classify_learner_return_value(Fixture())
    assert result[0] == 'INVALID_RESULT'
    assert result[1] is None
    assert 'untrusted_object' in result[3]
